def _observation(
    self,
    update_history: bool,
) -> np.ndarray:
    lidar = self._lidar48()
    goal_features, goal_dist, goal_angle = (
        self._goal_state()
    )
    clearance = self._clearance(lidar)

    current = np.concatenate(
        [
            lidar,
            goal_features,
            self.prev_action,
            clearance,
            np.array(
                [float(np.mean(lidar))],
                dtype=np.float32,
            ),
        ]
    ).astype(np.float32)

    if current.shape != (64,):
        raise RuntimeError(
            f"当前观测不是64维：{current.shape}"
        )

    frame = self._history_frame(
        lidar,
        goal_dist,
        goal_angle,
    )

    if update_history:
        self.history.append(frame)

    if not self.history:
        for _ in range(self.HISTORY_FRAMES):
            self.history.append(frame.copy())

    while len(self.history) < self.HISTORY_FRAMES:
        self.history.appendleft(
            self.history[0].copy()
        )

    observation = np.concatenate(
        [current, *list(self.history)]
    ).astype(np.float32)

    observation = np.clip(
        np.nan_to_num(
            observation,
            nan=0.0,
            posinf=10.0,
            neginf=-10.0,
        ),
        -10.0,
        10.0,
    ).astype(np.float32)

    if observation.shape != (112,):
        raise RuntimeError(
            f"最终观测不是112维：{observation.shape}"
        )

    return observation

