def _history_frame(
    self,
    lidar: np.ndarray,
    goal_dist: float,
    goal_angle: float,
) -> np.ndarray:
    sectors = np.array(
        [
            float(np.mean(chunk))
            for chunk in np.array_split(lidar, 8)
        ],
        dtype=np.float32,
    )

    return np.concatenate(
        [
            sectors,
            np.array(
                [
                    np.clip(goal_dist / 10.0, 0.0, 2.0),
                    np.clip(goal_angle / math.pi, -1.0, 1.0),
                    self.prev_action[0],
                    self.prev_action[1],
                ],
                dtype=np.float32,
            ),
        ]
    ).astype(np.float32)

