@staticmethod
def _clearance(lidar: np.ndarray) -> np.ndarray:
    angles = np.linspace(
        -0.75 * math.pi,
        0.75 * math.pi,
        lidar.size,
        dtype=np.float32,
    )

    masks = (
        np.ones(lidar.size, dtype=bool),
        np.abs(angles) <= math.radians(22.5),
        (
            (angles > math.radians(22.5))
            & (angles <= math.radians(110.0))
        ),
        (
            (angles < -math.radians(22.5))
            & (angles >= -math.radians(110.0))
        ),
    )

    return np.array(
        [
            float(np.min(lidar[mask]))
            if np.any(mask)
            else 1.0
            for mask in masks
        ],
        dtype=np.float32,
    )
